/**
 * A port of the `canonicaljson` package's three public encoders.
 *
 * All three return UTF-8 `bytes` (a `Uint8Array` here), which is why the
 * program's output is a `bytes` repr rather than plain text.  The canonical
 * form sorts keys and drops all whitespace; the pretty form sorts keys and
 * indents by four spaces.  Neither escapes non-ASCII, and neither tolerates
 * NaN or infinities.
 */

import { JSONEncoder } from './json/encoder.mjs';

const utf8 = new TextEncoder();

const canonicalEncoder = new JSONEncoder({
  allowNan: false,
  separators: [',', ':'],
  sortKeys: true,
});

const prettyEncoder = new JSONEncoder({
  allowNan: false,
  indent: 4,
  sortKeys: true,
});

/** `canonicaljson.encode_canonical_json()` */
export function encodeCanonicalJson(value) {
  return utf8.encode(canonicalEncoder.encode(value));
}

/** `canonicaljson.encode_pretty_printed_json()` */
export function encodePrettyPrintedJson(value) {
  return utf8.encode(prettyEncoder.encode(value));
}

/**
 * `canonicaljson.iterencode_canonical_json()` — yields each chunk of the
 * canonical form separately, encoded to UTF-8.
 */
export function* iterencodeCanonicalJson(value) {
  for (const chunk of canonicalEncoder.iterencode(value)) {
    yield utf8.encode(chunk);
  }
}
