/**
 * `json.encoder.encode_basestring()` — the `ensure_ascii=False` string escaper.
 *
 * Only the two structural characters and the C0 control range are touched;
 * every other code point, however exotic, is emitted verbatim and left for the
 * UTF-8 step to deal with.  In particular U+007F and the U+2028/U+2029 line
 * separators are *not* escaped.
 */

const ESCAPE_RE = /[\x00-\x1f\\"]/g;

const ESCAPE_DCT = Object.create(null);
ESCAPE_DCT['\\'] = '\\\\';
ESCAPE_DCT['"'] = '\\"';
ESCAPE_DCT['\b'] = '\\b';
ESCAPE_DCT['\f'] = '\\f';
ESCAPE_DCT['\n'] = '\\n';
ESCAPE_DCT['\r'] = '\\r';
ESCAPE_DCT['\t'] = '\\t';
for (let i = 0; i < 0x20; i += 1) {
  const ch = String.fromCharCode(i);
  if (ESCAPE_DCT[ch] === undefined) {
    ESCAPE_DCT[ch] = `\\u${i.toString(16).padStart(4, '0')}`;
  }
}

/** Return `text` as a JSON string literal, quotes included. */
export function encodeBasestring(text) {
  return `"${text.replace(ESCAPE_RE, (match) => ESCAPE_DCT[match])}"`;
}

