  [0x370, 0x3ff],     // Greek
  [0x400, 0x52f],     // Cyrillic
  [0x590, 0x6ff],     // Hebrew/Arabic (RTL)
  [0x900, 0x9ff],     // Devanagari/Bengali digits
  [0xe50, 0xe59],     // Thai digits
  [0x1680, 0x169f],   // Ogham
  [0x1c40, 0x1c4f],   // Lepcha (digits)
  [0x19d0, 0x19df],   // New Tai Lue digits (unaligned digit!)
  [0x2000, 0x206f],   // general punctuation (spaces, seps)
  [0x2070, 0x209f],   // super/subscript digits
