  [0xe000, 0xf8ff],   // private use
  [0xfb00, 0xfdff],   // presentation forms
  [0xfe00, 0xfeff],   // variation selectors / BOM
  [0xff00, 0xffef],   // fullwidth forms (fullwidth digits!)
  [0xfff0, 0xffff],   // specials / noncharacters
