  ' ', ' ', ' ', ' ', ' ', '　',
  '​', '‎', '‏', '᠎', '﻿', '�',
  '￾', '￿', '﷐', '́', '☃', '\u{1f600}',
  '\u{10ffff}', '\u{e0001}', '\u{1d7ce}', '０', '٠', '۰',
  '०', '০', '๐', '᧚', '᱀', '\u{104a0}',
