  '', ' ', '+', '-', '++1', '--1', '1.0', '1.', '.1', '1e5', '0x10', '0b1', '0o7', '1j',
  'abc', 'inf', 'nan', 'None', 'null', '1 2', '1,2', '_1', '1_', '1__2', '- 1', '1-', 'l',
